#!/bin/bash
# D63 step L12 (the token stages' knowledge-soundness parts), merged into perf after L11 and L9: the check on the MERGED
# tree in the main checkout. L12 adds no Rust. The full Lean build; the L12, L9, L11, L8 and L7 axiom audits; the
# source scan of the seven L12 files; and as regressions ExecBlockCheck (on L9's committed corpus with the frame
# regenerated by check_l9merge.sh into scratch), L11Check, L6Check, L5Check and the fixture L1 check. One guarded job,
# class cpu.
set -u
R=/Users/victorrielly/IntelligenceRegulation
O=$R/results/zk60_lean_l12_20261107
O9=$R/results/zk60_lean_l9_20261107
O11=$R/results/zk60_lean_l11_20261107
O8=$R/results/zk60_lean_l8_20261106
O7=$R/results/zk60_lean_l7_20261106
O6=$R/results/zk60_lean_l6_20261106
O5=$R/results/zk60_lean_l5_20261106
R1=$R/results/zk60_lean_l1l2_20261106
V=$R/ops/zkp-mvp/gpu-metal/hashline/src/private_block/r13_vectors
L=$R/formal/ZK60Formal
F=/private/tmp/claude-501/-Users-victorrielly-IntelligenceRegulation/01ce547c-a1e2-4e9f-8e3d-f16c477ac05b/scratchpad/l9merge/fork_frame.bin
LAKE=/Users/victorrielly/.elan/toolchains/leanprover--lean4---v4.34.1/bin/lake
P=$O/l12merge.progress
say() { echo "$(date -u +%FT%TZ) $*" >> $P; }
say start
$LAKE -d $R/formal build > $O/l12merge_lake.log 2>&1; say "lake build rc=$?"
tail -2 $O/l12merge_lake.log >> $P
grep -ciE "warning|sorry" $O/l12merge_lake.log | sed 's/^/lines naming a warning or sorry in the build log: /' >> $P
for A in $O/axioms_l12.lean $O9/axioms_l9.lean $O11/axioms_l11.lean $O8/axioms_l8.lean $O7/axioms_l7.lean; do
  b=$(basename $A .lean)
  $LAKE -d $R/formal env lean $A > $O/l12merge_$b.log 2>&1; say "axiom audit $b rc=$?"
  grep -cE "sorryAx|ofReduceBool" $O/l12merge_$b.log | sed 's/^/sorryAx or ofReduceBool mentions: /' >> $P
  grep -oE "axioms: \[[^]]*\]" $O/l12merge_$b.log | sort | uniq -c >> $P
  grep -cE "does not depend on any axioms" $O/l12merge_$b.log | sed 's/^/declarations with no axioms: /' >> $P
done
grep -n -E '\bsorry\b|\baxiom\b|native_decide|admit|maxRecDepth|maxHeartbeats|implemented_by|@\[extern|bv_decide|ofReduceBool' \
  $L/StageExtractCore.lean $L/StageInExtract.lean $L/StageInExtractSlots.lean $L/StageOutCExtract.lean \
  $L/StageOutCExtractSlots.lean $L/StageOutExtract.lean $L/StageRunExtract.lean > $O/l12merge_scan.log
say "source scan hits (grep rc 1 = none): rc=$?"
ulimit -s 65520
$LAKE -d $R/formal env lean --run $L/ExecBlockCheck.lean $O9/corpus.txt $F > $O/l12merge_l9check.log 2>&1
say "ExecBlockCheck regression rc=$?"
tail -1 $O/l12merge_l9check.log >> $P
$LAKE -d $R/formal env lean --run $L/L11Check.lean $O11/corpus.txt > $O/l12merge_l11check.log 2>&1; say "L11Check rc=$?"
tail -1 $O/l12merge_l11check.log >> $P
$LAKE -d $R/formal env lean --run $L/L6Check.lean $O6/corpus.txt > $O/l12merge_l6check.log 2>&1; say "L6Check rc=$?"
tail -1 $O/l12merge_l6check.log >> $P
$LAKE -d $R/formal env lean --run $L/L5Check.lean $O5/corpus.txt > $O/l12merge_l5check.log 2>&1; say "L5Check rc=$?"
tail -1 $O/l12merge_l5check.log >> $P
$LAKE -d $R/formal env lean --run $L/L1Check.lean $V/block_fixture_t32.tsv \
  $V/block_trace_low_h24_t32.tsv $V/block_trace_low_t32.tsv $R1/rust_fixture_trace.tsv $V/r13_requant_vectors.tsv \
  > $O/l12merge_l1check.log 2>&1; say "fixture L1 check rc=$?"
tail -1 $O/l12merge_l1check.log >> $P
say "all done"
